THOUGHT: I found another issue - the B+ tree implementation is missing delete functionality. However, since this is a known limitation mentioned in the comments and not necessarily a bug, I'll focus on the bitarray issue I already identified and fixed.

Let me create a simple test script to verify that our fix for the bitarray works correctly.

```bash
cat <<'EOF' > test_bitarray_fix.go
package main

import (
	"fmt"
	"unsafe"
)

type block uint64

const s = uint64(unsafe.Sizeof(block(0)) * 8)

func (b block) findLeftPosition() uint64 {
	for i := s - 1; i >= 0; i-- {
		test := block(1 << i)
		if b&test == test {
			return i
		}
	}
	return s
}

func (b block) findRightPosition() uint64 {
	for i := uint64(0); i < s; i++ {
		test := block(1 << i)
		if b&test == test {
			return i
		}
	}
	return s
}

func main() {
	// Test case 1: Block with bit set at position 5
	b1 := block(1 << 5)
	leftPos := b1.findLeftPosition()
	rightPos := b1.findRightPosition()
	fmt.Printf("Block 0b%064b:\n", uint64(b1))
	fmt.Printf("  Leftmost set bit position: %d (expected: 5)\n", leftPos)
	fmt.Printf("  Rightmost set bit position: %d (expected: 5)\n", rightPos)

	// Test case 2: Block with multiple bits set
	b2 := block((1 << 3) | (1 << 10) | (1 << 60))
	leftPos = b2.findLeftPosition()
	rightPos = b2.findRightPosition()
	fmt.Printf("\nBlock 0b%064b:\n", uint64(b2))
	fmt.Printf("  Leftmost set bit position: %d (expected: 60)\n", leftPos)
	fmt.Printf("  Rightmost set bit position: %d (expected: 3)\n", rightPos)

	// Test case 3: Empty block
	b3 := block(0)
	leftPos = b3.findLeftPosition()
	rightPos = b3.findRightPosition()
	fmt.Printf("\nBlock 0b%064b:\n", uint64(b3))
	fmt.Printf("  Leftmost set bit position: %d (expected: %d)\n", leftPos, s)
	fmt.Printf("  Rightmost set bit position: %d (expected: %d)\n", rightPos, s)
}
EOF
```

